<?php $title='Mailkonfiguration'; ?>
<div class="page-header"><div><p class="eyebrow">Administration · E-Mail</p><h1>Standort-E-Mail-Benachrichtigungen</h1><p>Betriebliche Nachrichten gehen ausschließlich an Standortadressen, niemals an private Mitarbeiteradressen.</p></div></div>
<div class="notice warning"><strong>Testphase:</strong> Solange der globale Versand deaktiviert ist, wird keine E-Mail tatsächlich versendet. Queue-Einträge werden als unterdrückt protokolliert.</div>
<form method="post" action="<?= e(url('admin/mail')) ?>" class="panel form-grid"><?= csrf_field() ?><label class="check-row span-2"><input type="checkbox" name="global_enabled" value="1" <?= $settings['global_enabled']?'checked':'' ?>><span><strong>Globalen Mailversand aktivieren</strong></span></label><label>Absendername<input name="from_name" value="<?= e($settings['from_name']) ?>" required></label><label>Absenderadresse<input type="email" name="from_address" value="<?= e($settings['from_address']) ?>" required></label>
<?php foreach($locations as $l):?><fieldset class="span-2 checkbox-panel"><legend><?= e($l['name']) ?></legend><div class="form-grid"><label>Standortadresse<input value="<?= e($l['email_address']) ?>" disabled></label><label>Mailmodus<select name="locations[<?= (int)$l['id'] ?>][mail_mode]"><option value="disabled" <?= $l['mail_mode']==='disabled'?'selected':'' ?>>Deaktiviert</option><option value="test" <?= $l['mail_mode']==='test'?'selected':'' ?>>Testmodus</option><option value="production" <?= $l['mail_mode']==='production'?'selected':'' ?>>Produktiv</option></select></label><label class="span-2">Testadresse<input type="email" name="locations[<?= (int)$l['id'] ?>][mail_test_address]" value="<?= e($l['mail_test_address']??'') ?>"></label></div></fieldset><?php endforeach;?><div class="span-2 form-actions"><button class="button primary" type="submit">Mailkonfiguration speichern</button></div></form>
<div class="panel"><h2>Letzte Queue-Einträge</h2><div class="table-wrap"><table><thead><tr><th>Zeit</th><th>Standort</th><th>Auslöser</th><th>Betreff</th><th>Status</th></tr></thead><tbody><?php foreach($queue as $q):?><tr><td><?= e(format_datetime($q['created_at'])) ?></td><td><?= e($q['location_name']) ?></td><td><?= e($q['trigger_code']) ?></td><td><?= e($q['subject']) ?></td><td><?= e($q['status']) ?></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="panel"><h2>E-Mail-Protokoll</h2><div class="table-wrap"><table><thead><tr><th>Zeit</th><th>Standort</th><th>Ziel</th><th>Auslöser</th><th>Betreff</th><th>Status</th><th>Modus</th></tr></thead><tbody><?php foreach($log as $m):?><tr><td><?= e(format_datetime($m['occurred_at'])) ?></td><td><?= e($m['location_name']??'–') ?></td><td><?= e($m['target_address']) ?></td><td><?= e($m['trigger_code']) ?></td><td><?= e($m['subject']) ?></td><td><?= e($m['status']) ?></td><td><?= e($m['mail_mode']) ?></td></tr><?php endforeach;?></tbody></table></div></div>
